const orders = {
  'WV-1001': { status: 'Processing', carrier: null, tracking: null, eta: '15 Aug 2026', note: 'Order confirmed, preparing for dispatch.' },
  'WV-1002': { status: 'Shipped', carrier: 'Delhivery', tracking: 'DL4471209IN', eta: '13 Aug 2026', note: 'Package left the warehouse.' },
  'WV-1003': { status: 'Out for Delivery', carrier: 'Bluedart', tracking: 'BD9982341IN', eta: '12 Aug 2026', note: 'Out for delivery today.' },
  'WV-1004': { status: 'Delivered', carrier: 'Delhivery', tracking: 'DL5561092IN', eta: '10 Aug 2026', note: 'Delivered and signed for.' },
  'WV-1005': { status: 'Exception', carrier: 'Bluedart', tracking: 'BD1120983IN', eta: null, note: 'Marked delivered by carrier but customer reports non-receipt. Needs human investigation.' }
};

const query = $input.first().json.query || {};
const body = $input.first().json.body || {};
const orderId = (query.order_id || body.order_id || '').toString().trim().toUpperCase();
const email = (query.email || body.email || '').toString().trim();

const order = orders[orderId];

if (!order) {
  return [{
    json: {
      found: false,
      order_id: orderId,
      message: 'No order found matching this Order ID.'
    }
  }];
}

return [{
  json: {
    found: true,
    order_id: orderId,
    email_provided: email,
    status: order.status,
    carrier: order.carrier,
    tracking_number: order.tracking,
    estimated_delivery: order.eta,
    note: order.note
  }
}];

